  /* How hard each kind of thing hits. A trap hits only while armed. */
  let damage_dealt =
    fun
    | Player(_) => 3
    | Monster({kind: Goblin, _}) => 1
    | Monster({kind: Orc, _}) => 4
    | Monster({kind: Skeleton, _}) => 2
    | Trap({damage, armed: true}) => damage
    | Trap({armed: false, _}) => 0;

  /* How much of a blow each kind of thing shrugs off. */
  let armor =
    fun
    | Player(_) => 1
    | Monster({kind: Skeleton, _}) => 1
    | Monster(_) => 0
    | Trap(_) => 0;

  /* Damage after armor: at least one point lands when the blow had any force. */
  let damage_taken = (~attacker, ~defender) => {
    let raw = damage_dealt(attacker);
    raw == 0 ? 0 : max(1, raw - armor(defender));
  };

  let wound = (c, damage) =>
    switch (c) {
    | Player(p) => Player({...p, hp: p.hp - damage})
    | Monster(m) => Monster({...m, hp: m.hp - damage})
    | Trap(_) => c
    };

  let attack = (~attacker, ~defender) =>
    switch (defender) {
    | Trap(_) => NoEffect
    | Player(_)
    | Monster(_) =>
      let damage = damage_taken(~attacker, ~defender);
      let survivor = wound(defender, damage);
      is_alive(survivor)
        ? Wounded({survivor, damage}) : Slain({damage: damage});
    };

  let%test "a player fells a goblin in one blow" =
    attack(~attacker=new_player(~hp=10, ~inventory=[]), ~defender=spawn(Goblin))
    == Slain({damage: 3});

  let%test "a player wounds an orc for full damage" =
    attack(~attacker=new_player(~hp=10, ~inventory=[]), ~defender=spawn(Orc))
    == Wounded({survivor: Monster({kind: Orc, hp: 5}), damage: 3});

  let%test "a skeleton's armor takes the edge off" =
    attack(~attacker=new_player(~hp=10, ~inventory=[]), ~defender=spawn(Skeleton))
    == Wounded({survivor: Monster({kind: Skeleton, hp: 3}), damage: 2});

  let%test "a goblin still lands one point on an armored player" =
    attack(~attacker=spawn(Goblin), ~defender=new_player(~hp=10, ~inventory=[]))
    == Wounded({survivor: Player({hp: 9, max_hp: 10, inventory: []}), damage: 1});

  let%test "a disarmed trap does nothing" =
    attack(~attacker=Trap({damage: 5, armed: false}), ~defender=new_player(~hp=10, ~inventory=[]))
    == Wounded({survivor: Player({hp: 10, max_hp: 10, inventory: []}), damage: 0});

  let%test "traps cannot be fought" =
    attack(~attacker=new_player(~hp=10, ~inventory=[]), ~defender=trap(2)) == NoEffect;
};

