  List.fold_left((s, c) => Turn.step(c, s), state, commands);

let final = play(commands, start);

let transcript = s =>
  Render.describe(s)
  ++ (List.map(Render.narrate, Turn.log(s)) |> String.concat("\n"))
  ++ "\n";

/* --- tests on the final state --- */

let%test "five commands take five turns" = Turn.turn(final) == 5;

let%test "the hero ends at the goblin's old spot, wounded, with only the key" =
  Turn.player(final)
  == Some((
       Pos.make(2, 1),
       Creatures.Player({
         hp: 4,
         max_hp: 10,
         inventory: [Key(Brass)],
       }),
     ));

let%test "both monsters are gone and the trap is untouched" =
  Turn.at(final, Pos.make(2, 1)) != None
  && Turn.at(final, Pos.make(3, 1)) == None
  && Turn.at(final, Pos.make(3, 3)) == Some(Creatures.trap(2))
  && List.length(Turn.creatures(final)) == 2;

let%test "the doors are as they were" =
  Dungeon.tile_at(Turn.room(final), Pos.make(7, 2))
  == Door(Dungeon.Tile.plain_door)
  && Dungeon.tile_at(Turn.room(final), Pos.make(3, 5))
  == Door(Dungeon.Tile.locked_door(Brass));

/* --- tests on the event log --- */

let%test "the log tells the whole story in order" = {
  let wounded_orc =
    Creatures.Monster({
      kind: Orc,
      hp: 5,
    });
  let hero_at = (hp, inventory) =>
    Creatures.Player({
      hp,
      max_hp: 10,
      inventory,
    });
  let full_pack = [Creatures.Potion(3), Key(Brass)];
  Turn.log(final)
  == [
       /* turn 1 */
       Struck({
         attacker: hero,
         defender: goblin,
         damage: 3,
         critical: false,
       }),
       Slain(goblin),
       /* turn 2 */
       Moved(Pos.make(2, 1)),
       Struck({
         attacker: orc,
         defender: hero,
         damage: 3,
         critical: false,
       }),
       /* turn 3 */
       Struck({
         attacker: hero_at(7, full_pack),
         defender: orc,
         damage: 3,
         critical: false,
       }),
       Struck({
         attacker: wounded_orc,
         defender: hero_at(7, full_pack),
         damage: 3,
         critical: false,
       }),
       /* turn 4 */
       Used({
         item: Potion(3),
         effect: Healed(3),
       }),
       Struck({
         attacker: wounded_orc,
         defender: hero_at(7, [Key(Brass)]),
         damage: 3,
         critical: false,
       }),
       /* turn 5 */
       Struck({
         attacker: hero_at(4, [Key(Brass)]),
         defender: wounded_orc,
         damage: 6,
         critical: true,
       }),
       Slain(wounded_orc),
     ];
};

let%test "two things were slain and one blow was critical" = {
  let slain =
    List.filter(
      fun
      | Turn.Slain(_) => true
      | _ => false,
      Turn.log(final),
    );
  let criticals =
    List.filter(
      fun
      | Turn.Struck({critical: true, _}) => true
      | _ => false,
      Turn.log(final),
    );
  List.length(slain) == 2 && List.length(criticals) == 1;
};

let%test "nobody died and nothing was blocked" =
  !List.mem(Turn.Died, Turn.log(final))
  && !
       List.exists(
         fun
         | Turn.Blocked(_) => true
         | _ => false,
         Turn.log(final),
       );

/* --- the picture --- */

let%test "the final room draws as expected" =
  Render.describe(final) == "########\n"
  ++ "#.@....#\n"
  ++ "#......+\n"
  ++ "#..^...#\n"
  ++ "#.....>#\n"
  ++ "###*####\n"
  ++ "########\n"
  ++ "Turn 5  HP 4/10  Pack: a brass key\n";

let%test "the transcript ends with the orc falling" = {
  let lines = String.split_on_char('\n', transcript(final));
  List.nth(lines, List.length(lines) - 2) == "The orc falls.";
};

files.lib/rules.rei:
/* When a blow lands harder than usual. */
module Crit: {
  /* The luck of one blow. Comes from the turn counter, so games are repeatable. */
  type roll;

  /* A critical lands on every roll that is a multiple of this. */
  let every: int;

  /* How many times harder a critical blow strikes. */
  let multiplier: int;

  /* The roll used for every blow struck on a given turn. */
  let roll_for_turn: int => roll;

  /* True when this creature is able to land a critical. Traps are not. */
  let can_crit: Creatures.t => bool;

  /* True when the attacker's blow on this roll is a critical. */
  let lands: (~attacker: Creatures.t, roll) => bool;
};

/* What one blow does: the points it takes off, and whether it was a critical. */
type hit = {
  damage: int,
  critical: bool,
};

/* How many points a creature's blow carries before armor. A disarmed trap carries none. */
let damage_dealt: Creatures.t => int;

/* How many points a creature's armor absorbs. */
let armor: Creatures.t => int;

/* The damage a blow does after criticals and the defender's armor.
   At least one point lands when the blow had any force. */
let blow:
  (~attacker: Creatures.t, ~defender: Creatures.t, ~roll: Crit.roll) => hit;

files.lib/rules.re:
module Crit = {
  type roll = int;

  let every = 5;

  let multiplier = 2;

  let roll_for_turn = turn => turn;

  let can_crit =
    fun
    | Creatures.Player(_)
    | Creatures.Monster(_) => true
    | Creatures.Trap(_) => false;

  let lands = (~attacker, roll) =>
    can_crit(attacker) && roll > 0 && roll mod every == 0;

  let%test "a critical lands on every fifth roll" =
    lands(~attacker=Creatures.spawn(Goblin), 5)
    && lands(~attacker=Creatures.spawn(Goblin), 10)
    && !lands(~attacker=Creatures.spawn(Goblin), 4)
    && !lands(~attacker=Creatures.spawn(Goblin), 0);

  let%test "traps never land a critical" =
    !lands(~attacker=Creatures.trap(3), 5);
};

type hit = {
  damage: int,
  critical: bool,
};

let damage_dealt =
  fun
  | Creatures.Player(_) => 3
  | Creatures.Monster({kind: Goblin, _}) => 1
  | Creatures.Monster({kind: Orc, _}) => 4
  | Creatures.Monster({kind: Skeleton, _}) => 2
  | Creatures.Trap({damage, armed: true}) => damage
  | Creatures.Trap({armed: false, _}) => 0;

let armor =
  fun
  | Creatures.Player(_) => 1
  | Creatures.Monster({kind: Skeleton, _}) => 1
  | Creatures.Monster(_) => 0
  | Creatures.Trap(_) => 0;

let blow = (~attacker, ~defender, ~roll) => {
  let raw = damage_dealt(attacker);
  if (raw == 0) {
    {
      damage: 0,
      critical: false,
    };
  } else {
    let critical = Crit.lands(~attacker, roll);
    let force = critical ? raw * Crit.multiplier : raw;
    {
      damage: max(1, force - armor(defender)),
      critical,
    };
  };
};

let hero = Creatures.new_player(~hp=10, ~inventory=[]);

let%test "a skeleton's armor takes the edge off" =
  blow(~attacker=hero, ~defender=Creatures.spawn(Skeleton), ~roll=1)
  == {
       damage: 2,
       critical: false,
     };

let%test "a goblin still lands one point on an armored player" =
  blow(~attacker=Creatures.spawn(Goblin), ~defender=hero, ~roll=1)
  == {
       damage: 1,
       critical: false,
     };

let%test "a disarmed trap has no force at all" =
  blow(
    ~attacker=
      Creatures.Trap({
        damage: 5,
        armed: false,
      }),
    ~defender=hero,
    ~roll=5,
  )
  == {
       damage: 0,
       critical: false,
     };

let%test "a critical blow doubles the force before armor" =
  blow(~attacker=hero, ~defender=Creatures.spawn(Skeleton), ~roll=5)
  == {
       damage: 5,
       critical: true,
     }
  && blow(~attacker=Creatures.spawn(Goblin), ~defender=hero, ~roll=5)
  == {
       damage: 1,
       critical: true,
     };

files.lib/creatures.rei:
/* Something a creature can carry and use. */
type item =
  | Potion(int) /* heals this many hit points */
  | Elixir /* heals to full */
  | Key(Dungeon.Tile.key); /* opens doors with the matching lock */

/* The kinds of monster that live in the dungeon. */
type kind =
  | Goblin
  | Orc
  | Skeleton;

/* The adventurer: current and full hit points, and what they carry. */
type player = {
  hp: int,
  max_hp: int,
  inventory: list(item),
};

/* A monster of some kind and its current hit points. */
type monster = {
  kind,
  hp: int,
};

/* A trap: how hard it bites, and whether it still can. */
type trap = {
  damage: int,
  armed: bool,
};

/* Anything that occupies a cell of the room. A trap is not alive, but it sits in the same list. */
type t =
  | Player(player)
  | Monster(monster)
  | Trap(trap);

/* The same type under another name, for use inside nested modules whose own t is something else. */
type creature = t;

/* The lower-case name of a kind of monster. */
let kind_name: kind => string;

/* What to call a creature in a message: "you", "orc", "a trap". */
let name: t => string;

/* The hit points a kind of monster starts with. */
let max_hp_of_kind: kind => int;

/* A player at full health carrying the given items. */
let new_player: (~hp: int, ~inventory: list(item)) => t;

/* A monster of a kind, at full health. */
let spawn: kind => t;

/* An armed trap that bites for the given damage. */
let trap: int => t;

/* Current hit points; None for a trap. */
let hp: t => option(int);

/* True while hit points are above zero. Traps are always "alive". */
let is_alive: t => bool;

/* Items and what they do. */
module Items: {
  type t = item;

  /* What applying an item did. */
  type effect =
    | Healed(int)
    | Nothing;

  /* The name of an item in a message. */
  let name: t => string;

  /* True when the creature is a player with the item in their pack. */
  let carries: (t, creature) => bool;

  /* The item's effect on a creature, with the creature afterwards. Keys have none. */
  let apply: (t, creature) => (creature, effect);

  /* Applies one copy of the item from a player's inventory. An item that had an
     effect is used up; one that had none stays in the pack.
     None when the creature is not a player or does not carry the item. */
  let use: (t, creature) => option((creature, effect));
};

/* Fights between creatures. */
module Combat: {
  /* What an attack did to the defender. */
  type outcome =
    | Wounded({
        survivor: creature,
        damage: int,
      })
    | Slain({damage: int})
    | NoEffect;

  /* The creature with that many hit points taken away. Traps are unchanged. */
  let wound: (creature, int) => creature;

  /* Lands a blow of the given damage on the defender. How much damage a blow
     carries is the business of Rules, not of this module. */
  let resolve: (~damage: int, creature) => outcome;
};

files.lib/dungeon.rei:
/* The tiles a room is made of. */
module Tile: {
  /* Whether a door stands open or shut. */
  type door_state =
    | Open
    | Closed;

  /* The kinds of key a lock can ask for. */
  type key =
    | Brass
    | Iron;

  /* What a door asks of whoever wants to open it. */
  type lock =
    | Unlocked
    | Locked(key);

  /* A door: open or shut, and what it takes to open it. */
  type door = {
    state: door_state,
    lock,
  };

  /* One cell of the dungeon. */
  type t =
    | Floor
    | Wall
    | Door(door)
    | Stairs;

  /* A shut door that anyone can open. */
  let plain_door: door;

  /* A shut door that only the holder of the key can open. */
  let locked_door: key => door;

  /* The lower-case name of a key: "brass", "iron". */
  let key_name: key => string;

  /* True when a creature can stand on the tile. A shut door blocks whether or not it is locked. */
  let passable: t => bool;
};

/* A rectangular grid of tiles. Cells outside the grid read as Wall. */
type room;

/* A room of the given size filled with one tile. */
let make: (~width: int, ~height: int, Tile.t) => room;

/* The number of columns. */
let width: room => int;

/* The number of rows. */
let height: room => int;

/* True when the position lies inside the grid. */
let in_bounds: (room, Pos.t) => bool;

/* The tile at a position; Wall for positions outside the grid. */
let tile_at: (room, Pos.t) => Tile.t;

/* A copy of the room with one tile replaced. Positions outside the grid are ignored. */
let set_tile: (room, Pos.t, Tile.t) => room;

/* True when a creature can stand at the position. */
let passable: (room, Pos.t) => bool;

/* Every position in the grid, row by row from the top left. */
let positions: room => list(Pos.t);

/* Ways of cutting shapes into a room. */
module Carve: {
  /* A floor rectangle with its top-left corner at origin, ringed by walls one cell thick. */
  let walled_rect: (room, ~origin: Pos.t, ~width: int, ~height: int) => room;

  /* Turns a wall into the given door. None when the position is not a wall. */
  let cut_door: (room, Pos.t, Tile.door) => option(room);

  /* Puts stairs on a floor cell. None when the position is not floor. */
  let place_stairs: (room, Pos.t) => option(room);
};

files.lib/render.rei:
/* The characters things are drawn with. */
module Glyph: {
  /* '.' floor, '#' wall, '>' stairs, '\'' open door, '+' shut door, '*' locked door. */
  let tile: Dungeon.Tile.t => char;

  /* '@' the player, 'g' 'o' 's' goblin, orc, skeleton, '^' an armed trap, ',' a sprung one. */
  let creature: Creatures.t => char;
};

/* The room as lines of text, one per row, with creatures drawn over the tiles they stand on. */
let map: Turn.state => string;

/* One line: the turn count, the player's hit points, and what they carry. */
let status: Turn.state => string;

/* The map, then the status line, each line ending in a newline. */
let describe: Turn.state => string;

/* One event told in a sentence. */
let narrate: Turn.event => string;

files.lib/turn.rei:
/* What the player asks to do on their turn. */
type command =
  | Move(Pos.dir) /* step that way; bumping a monster attacks it, bumping a shut door opens it if you have its key */
  | Attack(Pos.dir) /* strike whatever is one step that way; an armed trap is disarmed instead */
  | Use(Creatures.item) /* use an item from the inventory */
  | Wait; /* stand still */

/* One thing that happened during a turn, in the order it happened. */
type event =
  | Moved(Pos.t)
  | Blocked(Pos.t)
  | OpenedDoor(Pos.t)
  | UnlockedDoor(Pos.t, Dungeon.Tile.key) /* always followed by OpenedDoor */
  | DoorLocked(Pos.t, Dungeon.Tile.key) /* the player lacks this key */
  | Descended
  | Struck({
      attacker: Creatures.t,
      defender: Creatures.t,
      damage: int,
      critical: bool,
    })
  | Slain(Creatures.t)
  | SwungAtNothing(Pos.t)
  | Sprung({
      at: Pos.t,
      damage: int,
    })
  | Disarmed(Pos.t)
  | Used({
      item: Creatures.item,
      effect: Creatures.Items.effect,
    })
  | NoSuchItem(Creatures.item)
  | Waited
  | Died;

/* A room, who stands where in it, how many turns have passed, and what has happened. */
type state;

/* A game at turn zero with nothing in its log. Put the player in the creature list. */
let make:
  (~room: Dungeon.room, ~creatures: list((Pos.t, Creatures.t))) => state;

/* The room as it is now; doors may have been opened. */
let room: state => Dungeon.room;

/* The number of turns taken so far. */
let turn: state => int;

/* Everyone still in the room, with where they stand. */
let creatures: state => list((Pos.t, Creatures.t));

/* Everything that has happened, oldest first. */
let log: state => list(event);

/* Whoever stands at a position. */
let at: (state, Pos.t) => option(Creatures.t);

/* The player and where they stand, if they are in the room. */
let player: state => option((Pos.t, Creatures.t));

/* Carries out one command for the player, then lets every adjacent monster strike.
   Adds one to the turn counter and appends what happened to the log.
   A dead player takes no more turns: the state comes back unchanged. */
let step: (command, state) => state;

files.lib/dungeon.re:
module Tile = {
  type door_state =
    | Open
    | Closed;

  type key =
    | Brass
    | Iron;

  type lock =
    | Unlocked
    | Locked(key);

  type door = {
    state: door_state,
    lock,
  };

  type t =
    | Floor
    | Wall
    | Door(door)
    | Stairs;

  let plain_door = {
    state: Closed,
    lock: Unlocked,
  };

  let locked_door = key => {
    state: Closed,
    lock: Locked(key),
  };

  let key_name =
    fun
    | Brass => "brass"
    | Iron => "iron";

  let passable =
    fun
    | Floor
    | Stairs
    | Door({state: Open, _}) => true
    | Wall
    | Door({state: Closed, _}) => false;

  let%test "floor, stairs and open doors can be walked on" =
    passable(Floor)
    && passable(Stairs)
    && passable(
         Door({
           state: Open,
           lock: Locked(Iron),
         }),
       );

  let%test "walls and closed doors block, locked or not" =
    !passable(Wall)
    && !passable(Door(plain_door))
    && !passable(Door(locked_door(Brass)));
};

type room = {
  width: int,
  height: int,
  tiles: array(Tile.t) /* row-major: index = y * width + x */
};

let make = (~width, ~height, fill) => {
  width,
  height,
  tiles: Array.make(width * height, fill),
};

let width = r => r.width;

let height = r => r.height;

let in_bounds = (r, p) => {
  let (x, y) = (Pos.x(p), Pos.y(p));
  x >= 0 && y >= 0 && x < r.width && y < r.height;
};

let tile_at = (r, p) =>
  if (in_bounds(r, p)) {
    r.tiles[Pos.y(p) * r.width + Pos.x(p)];
  } else {
    Tile.Wall;
  };

let set_tile = (r, p, tile) =>
  if (in_bounds(r, p)) {
    let tiles = Array.copy(r.tiles);
    tiles[Pos.y(p) * r.width + Pos.x(p)] = tile;
    {
      ...r,
      tiles,
    };
  } else {
    r;
  };

let passable = (r, p) => Tile.passable(tile_at(r, p));

let positions = r => {
  let acc = ref([]);
  for (y in r.height - 1 downto 0) {
    for (x in r.width - 1 downto 0) {
      acc := [Pos.make(x, y), ...acc^];
    };
  };
  acc^;
};

let%test "outside the grid counts as wall" =
  tile_at(make(~width=3, ~height=3, Tile.Floor), Pos.make(3, 0))
  == Tile.Wall
  && tile_at(make(~width=3, ~height=3, Tile.Floor), Pos.make(0, -1))
  == Tile.Wall;

let%test "set_tile changes one cell and leaves the original room alone" = {
  let r = make(~width=2, ~height=2, Tile.Wall);
  let r' = set_tile(r, Pos.make(1, 1), Tile.Floor);
  tile_at(r', Pos.make(1, 1)) == Tile.Floor
  && tile_at(r', Pos.make(0, 0)) == Tile.Wall
  && tile_at(r, Pos.make(1, 1)) == Tile.Wall;
};

let%test "positions are listed row by row" =
  positions(make(~width=2, ~height=2, Tile.Floor))
  == [Pos.make(0, 0), Pos.make(1, 0), Pos.make(0, 1), Pos.make(1, 1)];

module Carve = {
  let walled_rect = (r, ~origin, ~width as w, ~height as h) => {
    let (ox, oy) = (Pos.x(origin), Pos.y(origin));
    let r = ref(r);
    for (y in oy - 1 to oy + h) {
      for (x in ox - 1 to ox + w) {
        let inside = x >= ox && x < ox + w && y >= oy && y < oy + h;
        let tile = inside ? Tile.Floor : Tile.Wall;
        r := set_tile(r^, Pos.make(x, y), tile);
      };
    };
    r^;
  };

  let cut_door = (r, p, door) =>
    switch (tile_at(r, p)) {
    | Tile.Wall => Some(set_tile(r, p, Tile.Door(door)))
    | _ => None
    };

  let place_stairs = (r, p) =>
    switch (tile_at(r, p)) {
    | Tile.Floor => Some(set_tile(r, p, Tile.Stairs))
    | _ => None
    };

  let rock = make(~width=6, ~height=6, Tile.Wall);

  let%test "walled_rect lays floor inside and wall around" = {
    let r = walled_rect(rock, ~origin=Pos.make(1, 1), ~width=2, ~height=2);
    tile_at(r, Pos.make(1, 1)) == Tile.Floor
    && tile_at(r, Pos.make(2, 2)) == Tile.Floor
    && tile_at(r, Pos.make(0, 0)) == Tile.Wall
    && tile_at(r, Pos.make(3, 1)) == Tile.Wall
    && tile_at(r, Pos.make(1, 3)) == Tile.Wall;
  };

  let%test "walled_rect leaves the rest of the rock alone" = {
    let r = walled_rect(rock, ~origin=Pos.make(1, 1), ~width=2, ~height=2);
    tile_at(r, Pos.make(5, 5)) == Tile.Wall;
  };

  let%test "a door can only be cut into a wall" = {
    let r = walled_rect(rock, ~origin=Pos.make(1, 1), ~width=2, ~height=2);
    switch (
      cut_door(r, Pos.make(3, 1), Tile.locked_door(Iron)),
      cut_door(r, Pos.make(1, 1), Tile.plain_door),
    ) {
    | (Some(r'), None) =>
      tile_at(r', Pos.make(3, 1))
      == Tile.Door({
           state: Closed,
           lock: Locked(Iron),
         })
    | _ => false
    };
  };

  let%test "stairs go on floor" = {
    let r = walled_rect(rock, ~origin=Pos.make(1, 1), ~width=2, ~height=2);
    switch (
      place_stairs(r, Pos.make(2, 2)),
      place_stairs(r, Pos.make(0, 0)),
    ) {
    | (Some(r'), None) => tile_at(r', Pos.make(2, 2)) == Tile.Stairs
    | _ => false
    };
  };
};

files.lib/pos.rei:
/* A cell on the dungeon grid. x grows east, y grows south. */
type t;

/* One of the four compass directions a thing can move in. */
type dir =
  | North
  | South
  | East
  | West;

/* The position at column x, row y. */
let make: (int, int) => t;

/* The column of a position. */
let x: t => int;

/* The row of a position. */
let y: t => int;

/* True when two positions name the same cell. */
let equal: (t, t) => bool;

/* Orders positions by row, then by column, for use in sets and maps. */
let compare: (t, t) => int;

/* The four directions, in the order North, South, East, West. */
let all_dirs: list(dir);

/* The cell one step away in a direction. */
let step: (t, dir) => t;

/* The four cells one step away, in the order of all_dirs. */
let neighbors: t => list(t);

/* The grid distance between two cells: steps along rows plus steps along columns. */
let manhattan: (t, t) => int;

/* A position written as "(x,y)". */
let to_string: t => string;

files.lib/render.re:
module Glyph = {
  let tile =
    fun
    | Dungeon.Tile.Floor => '.'
    | Dungeon.Tile.Wall => '#'
    | Dungeon.Tile.Stairs => '>'
    | Dungeon.Tile.Door({state: Open, _}) => '\''
    | Dungeon.Tile.Door({state: Closed, lock: Unlocked}) => '+'
    | Dungeon.Tile.Door({state: Closed, lock: Locked(_)}) => '*';

  let creature =
    fun
    | Creatures.Player(_) => '@'
    | Creatures.Monster({kind: Goblin, _}) => 'g'
    | Creatures.Monster({kind: Orc, _}) => 'o'
    | Creatures.Monster({kind: Skeleton, _}) => 's'
    | Creatures.Trap({armed: true, _}) => '^'
    | Creatures.Trap({armed: false, _}) => ',';

  let%test "doors show whether they are shut and locked" =
    tile(Door(Dungeon.Tile.plain_door)) == '+'
    && tile(Door(Dungeon.Tile.locked_door(Iron))) == '*'
    && tile(
         Door({
           state: Open,
           lock: Locked(Iron),
         }),
       )
    == '\'';

  let%test "a sprung trap looks different from an armed one" =
    creature(Creatures.trap(2)) == '^'
    && creature(
         Creatures.Trap({
           damage: 2,
           armed: false,
         }),
       )
    == ',';
};

let cell = (s, p) =>
  switch (Turn.at(s, p)) {
  | Some(c) => Glyph.creature(c)
  | None => Glyph.tile(Dungeon.tile_at(Turn.room(s), p))
  };

let row = (s, y) =>
  String.init(Dungeon.width(Turn.room(s)), x => cell(s, Pos.make(x, y)));

let map = s =>
  List.init(Dungeon.height(Turn.room(s)), row(s)) |> String.concat("\n");

let pack =
  fun
  | [] => "nothing"
  | items => List.map(Creatures.Items.name, items) |> String.concat(", ");

let status = s =>
  switch (Turn.player(s)) {
  | Some((_, Creatures.Player({hp, max_hp, inventory}))) =>
    Printf.sprintf(
      "Turn %d  HP %d/%d  Pack: %s",
      Turn.turn(s),
      hp,
      max_hp,
      pack(inventory),
    )
  | _ => Printf.sprintf("Turn %d  No player", Turn.turn(s))
  };

let describe = s => map(s) ++ "\n" ++ status(s) ++ "\n";

let narrate = e =>
  Turn.(
    switch (e) {
    | Moved(p) => "You step to " ++ Pos.to_string(p) ++ "."
    | Blocked(p) => "Something solid at " ++ Pos.to_string(p) ++ "."
    | OpenedDoor(p) => "The door at " ++ Pos.to_string(p) ++ " swings open."
    | UnlockedDoor(_, key) =>
      "Your " ++ Dungeon.Tile.key_name(key) ++ " key turns in the lock."
    | DoorLocked(_, key) =>
      "The door is locked. It wants a "
      ++ Dungeon.Tile.key_name(key)
      ++ " key."
    | Descended => "You find the stairs down."
    | Struck({attacker, defender, damage, critical}) =>
      Printf.sprintf(
        "%s %s %s for %d%s.",
        String.capitalize_ascii(Creatures.name(attacker)),
        Creatures.name(attacker) == "you" ? "hit" : "hits",
        Creatures.name(defender),
        damage,
        critical ? " (critical!)" : "",
      )
    | Slain(c) => "The " ++ Creatures.name(c) ++ " falls."
    | SwungAtNothing(_) => "You swing at empty air."
    | Sprung({damage, _}) =>
      Printf.sprintf("A trap! It bites you for %d.", damage)
    | Disarmed(_) => "You disarm the trap."
    | Used({item, effect: Healed(n)}) =>
      Printf.sprintf(
        "You use %s and heal %d.",
        Creatures.Items.name(item),
        n,
      )
    | Used({item, effect: Nothing}) =>
      "You fiddle with " ++ Creatures.Items.name(item) ++ ". Nothing happens."
    | NoSuchItem(item) => "You have no " ++ Creatures.Items.name(item) ++ "."
    | Waited => "You wait."
    | Died => "You die."
    }
  );

/* --- tests --- */

let tiny = {
  Dungeon.(
    make(~width=5, ~height=4, Tile.Wall)
    |> Carve.walled_rect(_, ~origin=Pos.make(1, 1), ~width=3, ~height=2)
    |> Carve.cut_door(_, Pos.make(4, 1), Tile.plain_door)
    |> Option.get
    |> Carve.place_stairs(_, Pos.make(3, 2))
    |> Option.get
  );
};

let scene =
  Turn.make(
    ~room=tiny,
    ~creatures=[
      (
        Pos.make(1, 1),
        Creatures.new_player(~hp=10, ~inventory=[Potion(3), Key(Brass)]),
      ),
      (Pos.make(3, 1), Creatures.spawn(Orc)),
      (Pos.make(2, 2), Creatures.trap(2)),
    ],
  );

let%test "the room is drawn with creatures over the tiles" =
  describe(scene) == "#####\n"
  ++ "#@.o+\n"
  ++ "#.^>#\n"
  ++ "#####\n"
  ++ "Turn 0  HP 10/10  Pack: a potion (+3), a brass key\n";

let%test "an empty pack says so" =
  status(
    Turn.make(
      ~room=tiny,
      ~creatures=[
        (Pos.make(1, 1), Creatures.new_player(~hp=4, ~inventory=[])),
      ],
    ),
  )
  == "Turn 0  HP 4/4  Pack: nothing";

let%test "blows are narrated from the right side" =
  narrate(
    Struck({
      attacker: Creatures.spawn(Orc),
      defender: Creatures.new_player(~hp=10, ~inventory=[]),
      damage: 3,
      critical: true,
    }),
  )
  == "Orc hits you for 3 (critical!)."
  && narrate(
       Struck({
         attacker: Creatures.new_player(~hp=10, ~inventory=[]),
         defender: Creatures.spawn(Goblin),
         damage: 3,
         critical: false,
       }),
     )
  == "You hit goblin for 3.";

